void setArr(vec2 i, int N, out ivec2 arr[8])
{
        int ind, n ;  
        arr[0].x=0; arr[0].y=1; n = 2;
        for(int j=1; j<N; j++)
        {
                ind = int(float(n+1)*hash(i + vec2(N, j)*vec2(.123, .456)))%(n+1);
                for(int i=0; i<N;i++)
                {
                        if(arr[i].x>=ind)arr[i].x+=2;
                        if(arr[i].y>=ind)arr[i].y+=2;
                }
                arr[j].x = ind;
                arr[j].y = ind+1;
                n += 2;
        }
        //if(N==8) // 4 or 8 or comment
        //if(iMouse.y>iResolution.y*.5)     
        if(long){ llh(N,arr);}
}


