float dline(vec2 a, vec2 b, vec2 p)//0046
{
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}

float dring(vec2 p, vec2 np, vec2 q, vec2 nq, vec2 u) // 0023
{// 求任意两条线段之间的“圆弧”
        vec2 c;
        float r0, r,d=9999.;
        if(abs(nq.x *  np.y -  nq.y *  np.x)<.01) // dot(np, nq)
        {
                if( dot(np,nq)> 0.){
                        c = (p+q)/2.;
                        r0 = length(p-c);
                        r = length(u-c);
                        d = abs(r-r0);
                }else{
                        d = dline(p,q,u);
                }
        }else{ 
                        float e =  p.x *  np.y -  np.x *  p.y,
                              f =  q.x *  nq.y -  nq.x *  q.y,
                              g =  nq.x *  np.y -  nq.y *  np.x;

                        c = ( nq * e -  np * f) / g;
                        r0 = length(p-c);
                        r = length(u-c);
                        d = abs(r-r0);
        }
        return d;
}

float dCur(vec2 f, vec2 i, int N)
{
        ivec2 arr[8];
        setArr(i, N, arr);
        // 0002
        float d = 1e8,
              agl ,//= 2.*PI/N,  
              h = .5*tan(PI/float(N))/3.; // 8 边形的六分之一

        for(int i=0; i<N; i++)
        {
                ivec2 a = arr[i], b = a/2, nvg = (a - b * 2) * 2 -1; 
                vec2 agl = 2.*PI/float(N)*vec2(b);

                vec2 u = vec2(cos(agl.x), sin(agl.x)), np = vec2(-u.y, u.x);
                vec2 p = u * .5 + float(nvg.x) * np * h;
                vec2 v = vec2(cos(agl.y), sin(agl.y)), nq = vec2(-v.y, v.x);
                vec2 q = v * .5 + float(nvg.y) * nq * h;
                d = min(d, dring(p, np, q, nq, f));
        }
        return d;
}

void mainImage(out vec4 O, vec2 u)
{
        vec2 R = iResolution.xy;
        u = 3.*(u+u - R) / R.y+iTime*.5;
        u = rot(PI/4.) * u;

        vec2 f, a, i, n = normalize(vec2(1));

        i = round(u), f = u - i, a = abs(f);

        float dt = dot(a,n);
        float dframe  = 9999.; 

        if(dt < .5) dframe = min(.5-a.x, .5-a.y);
        dframe = min(dframe, abs(.5 - dt)); 
        dframe = abs(dframe-.03);

        float dc1 = dCur(f,i, 8);

        i = round(u-.5)+.5, f = u - i;//, a = abs(f);
        f = rot(PI/4.)*f;

        float agl = PI/8.; // TAU / 16.
        float h = tan(agl); // 八边形的边长

        float dc2 = dCur(f/h, i, 4)*h;//2345 为了少写代码用通用的过程
        O.x = exp(-60. * dframe);
        if(dt<.5){
                O.y = smoothstep(0.02, 0.,dc1);// exp(-50.*dc1);
        }else{
                O.y = smoothstep(0.02, 0.,dc2);// exp(-50.*dc2);
        }
        O = vec4( .6-O.x * .12 - .5* O.y);//0053
        //O.yx -= exp(-55. * dframe);
}
